#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long row[61] = {0};
    row[0] = 1;
    for (long long r = 0; r < n; ++r) {
        for (long long c = 0; c <= r; ++c) {
            if (c > 0) putchar(' ');
            printf("%lld", row[c]);
        }
        putchar('\n');
        for (long long c = r + 1; c > 0; --c) {
            row[c] = row[c] + row[c - 1];
        }
    }
    return 0;
}
